#include "net.h"
#include "relu.h"
#include <memory>
#include <iostream>
#include <fstream>
#include <iomanip>
uint32_t value_at(size_t i){return uint32_t(int(i%2049)-1024);}
struct PoolState{std::array<AuthKey,3>key;std::array<uint32_t,4>x,mac;std::array<uint32_t,3>residual{};};
int main(int argc,char**argv){try{if(argc!=6)throw std::runtime_error("usage: crisp_pool dealer|0|1 groups threads port output.json");std::string role=argv[1];size_t groups=std::stoul(argv[2]),nt=std::stoul(argv[3]);int port=std::stoi(argv[4]);if(!groups||nt<1||nt>32)throw std::invalid_argument("dimensions");auto lo=[&](size_t t){return groups*t/nt;};auto hi=[&](size_t t){return groups*(t+1)/nt;};auto mode=ReluMode::paper_approx;size_t stride=3*auth_key_bytes(mode)+32;
 std::vector<std::unique_ptr<Socket>>dealer(nt),peer(nt);for(size_t t=0;t<nt;++t){dealer[t]=std::make_unique<Socket>();peer[t]=std::make_unique<Socket>();}double start=now();
 if(role=="dealer"){uint32_t mu=random_ring();parallel(nt,[&](size_t t){dealer[t]->accept_at(port+100+t);peer[t]->accept_at(port+200+t);dealer[t]->put(mu);dealer[t]->sync(false);peer[t]->sync(false);});double setup=now()-start;start=now();parallel(nt,[&](size_t t){for(size_t b=lo(t);b<hi(t);b+=64){size_t end=std::min(b+64,hi(t));std::vector<uint8_t>a,c;a.reserve((end-b)*stride);c.reserve((end-b)*stride);for(size_t i=b;i<end;++i){for(int j=0;j<3;++j){auto k=generate_authenticated_relu(mu,mode);write_auth_key(a,k.first);write_auth_key(c,k.second);}for(int j=0;j<4;++j){uint32_t x=value_at(4*i+j),s=random_ring();put32(a,s);put32(c,x-s);}for(int j=0;j<4;++j){uint32_t x=value_at(4*i+j),s=random_ring();put32(a,s);put32(c,uint32_t(uint64_t(mu)*x)-s);}}dealer[t]->send(a.data(),a.size());peer[t]->send(c.data(),c.size());}});double offline=now()-start;std::ofstream o(argv[5]);o<<std::setprecision(12)<<"{\"groups\":"<<groups<<",\"comparisons\":"<<groups*3<<",\"offline_s\":"<<offline<<",\"setup_s\":"<<setup<<",\"key_bytes\":"<<groups*3*2*auth_key_bytes(mode)<<",\"input_sharing_fixture_bytes\":"<<groups*64<<"}\n";return 0;}
 int party=std::stoi(role);if(party<0||party>1)throw std::invalid_argument("party");uint32_t mu=0;parallel(nt,[&](size_t t){dealer[t]->connect_to(port+(party?200:100)+t);if(!party){auto v=dealer[t]->get<uint32_t>();if(t==0)mu=v;peer[t]->accept_at(port+t);}else peer[t]->connect_to(port+t);});double setup=now()-start;std::vector<std::vector<PoolState>>state(nt);parallel(nt,[&](size_t t){dealer[t]->sync(true);std::vector<uint8_t>wire((hi(t)-lo(t))*stride);dealer[t]->recv(wire.data(),wire.size());const uint8_t*p=wire.data(),*e=p+wire.size();state[t].resize(hi(t)-lo(t));for(auto&s:state[t]){for(auto&k:s.key)k=read_auth_key(p,e,mode);for(auto&x:s.x)x=get32(p,e);for(auto&m:s.mac)m=get32(p,e);}peer[t]->sync(!party);});std::vector<uint64_t>base(nt);for(size_t t=0;t<nt;++t)base[t]=peer[t]->sent;
 start=now();parallel(nt,[&](size_t t){size_t n=state[t].size();std::vector<uint32_t>a(2*n),b(2*n);for(int round=0;round<2;++round){size_t pairs=round?1:2;for(size_t i=0;i<n;++i)for(size_t j=0;j<pairs;++j){auto&s=state[t][i];int key=round?2:j;int lhs=round?0:2*j,rhs=round?1:2*j+1;a[i*pairs+j]=s.x[lhs]-s.x[rhs]+s.key[key].value.r;}size_t bytes=n*pairs*4;if(!party){peer[t]->send(a.data(),bytes);peer[t]->recv(b.data(),bytes);}else{peer[t]->recv(b.data(),bytes);peer[t]->send(a.data(),bytes);}for(size_t i=0;i<n;++i){auto&s=state[t][i];std::array<uint32_t,2>ox{},om{};for(size_t j=0;j<pairs;++j){int key=round?2:j;int lhs=round?0:2*j,rhs=round?1:2*j+1;auto y=evaluate_authenticated_relu(party,s.key[key],a[i*pairs+j]+b[i*pairs+j]);ox[j]=s.x[rhs]+y.value;om[j]=s.mac[rhs]+y.mac;s.residual[key]=y.input_mac-(s.mac[lhs]-s.mac[rhs]);}for(size_t j=0;j<pairs;++j){s.x[j]=ox[j];s.mac[j]=om[j];}}}});double online=now()-start;uint64_t bytes=0;for(size_t t=0;t<nt;++t)bytes+=peer[t]->sent-base[t];size_t bad=0;
 for(size_t t=0;t<nt;++t){std::vector<uint32_t>v(state[t].size()*5);if(party){for(size_t i=0;i<state[t].size();++i){auto&s=state[t][i];v[5*i]=s.x[0];v[5*i+1]=s.mac[0];for(int j=0;j<3;++j)v[5*i+2+j]=s.residual[j];}peer[t]->send(v.data(),v.size()*4);}else{peer[t]->recv(v.data(),v.size()*4);for(size_t i=0;i<state[t].size();++i){auto&s=state[t][i];int32_t expect=INT32_MIN;for(int j=0;j<4;++j)expect=std::max(expect,int32_t(value_at(4*(lo(t)+i)+j)));uint32_t y=s.x[0]+v[5*i];bad+=y!=uint32_t(expect)||uint32_t(s.mac[0]+v[5*i+1])!=uint32_t(uint64_t(mu)*y);for(int j=0;j<3;++j)bad+=uint32_t(s.residual[j]+v[5*i+2+j])!=0;}}}
 std::ofstream o(argv[5]);o<<std::setprecision(12)<<"{\"party\":"<<party<<",\"groups\":"<<groups<<",\"inputs\":"<<4*groups<<",\"comparisons\":"<<3*groups<<",\"rounds\":2,\"online_s\":"<<online<<",\"online_sent_bytes\":"<<bytes<<",\"setup_s\":"<<setup<<",\"validation_errors\":"<<bad<<",\"mode\":\"paper_approx\",\"malicious_security_complete\":false}\n";return bad?2:0;
 }catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
